fix.code:
interface PaymentGateway {
    PaymentMethod method();                 // mỗi cài đặt tự khai báo nó phục vụ phương thức nào
    PaymentResult pay(Order order);
}

@Component
class ZaloPayGateway implements PaymentGateway {
    public PaymentMethod method() { return PaymentMethod.ZALOPAY; }
    public PaymentResult pay(Order order) { /* gọi API ZaloPay */ }
}

@Service
class CheckoutService {
    private final Map<PaymentMethod, PaymentGateway> gateways = new EnumMap<>(PaymentMethod.class);

    CheckoutService(List<PaymentGateway> all) {
        for (PaymentGateway gateway : all) {
            PaymentGateway previous = gateways.put(gateway.method(), gateway);
            if (previous != null) {
                throw new IllegalStateException("Hai gateway cho " + gateway.method());
            }
        }
        EnumSet<PaymentMethod> missing = EnumSet.allOf(PaymentMethod.class);
        missing.removeAll(gateways.keySet());
        if (!missing.isEmpty()) {
            throw new IllegalStateException("Thiếu gateway cho " + missing);
        }
    }

    PaymentResult pay(Order order) {
        return gateways.get(order.method()).pay(order);
    }
}
